import{_ as t,C as r,o as n,c as l,a3 as i,b as o,w as e,a as m,E as k,a4 as d}from"./chunks/framework.BvvarXmc.js";const u="/screenshots/kantin-pos.png",M=JSON.parse('{"title":"Transaksi Kasir POS & Scan Kartu RFID","description":"","frontmatter":{},"headers":[],"relativePath":"panduan-kantin/pos-kasir.md","filePath":"panduan-kantin/pos-kasir.md","lastUpdated":null}'),g={name:"panduan-kantin/pos-kasir.md"};function p(h,a,c,b,S,P){const s=r("Mermaid");return n(),l("div",null,[a[1]||(a[1]=i('<h1 id="transaksi-kasir-pos-scan-kartu-rfid" tabindex="-1">Transaksi Kasir POS &amp; Scan Kartu RFID <a class="header-anchor" href="#transaksi-kasir-pos-scan-kartu-rfid" aria-label="Permalink to &quot;Transaksi Kasir POS &amp; Scan Kartu RFID&quot;">​</a></h1><p>Aplikasi kasir <strong>Point of Sale (POS) Kantin</strong> dirancang khusus untuk melayani transaksi belanja siswa dengan kecepatan tinggi di jam istirahat sekolah yang padat.</p><p>Kasir dapat dioperasikan menggunakan komputer, laptop, tablet, atau mesin POS layar sentuh dengan scanner kartu RFID terhubung via USB.</p><hr><h2 id="tampilan-antarmuka-kasir-pos" tabindex="-1">Tampilan Antarmuka Kasir POS <a class="header-anchor" href="#tampilan-antarmuka-kasir-pos" aria-label="Permalink to &quot;Tampilan Antarmuka Kasir POS&quot;">​</a></h2><p>Berikut adalah tampilan antarmuka resmi kasir POS kantin sekolah:</p><p><img src="'+u+'" alt="Sistem POS Kantin"></p><hr><h2 id="alur-transaksi-kasir-pos" tabindex="-1">Alur Transaksi Kasir POS <a class="header-anchor" href="#alur-transaksi-kasir-pos" aria-label="Permalink to &quot;Alur Transaksi Kasir POS&quot;">​</a></h2>',9)),(n(),o(d,null,{default:e(()=>[k(s,{id:"mermaid-23",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%221.%20Identifikasi%20Pembeli%20via%20RFID%20%2F%20NISN%22%5D%20--%3E%20B%5B%222.%20Pilih%20Mode%20Transaksi%22%5D%0A%20%20%20%20B%20--%3E%7CMode%20Menu%7C%20C%5B%22Pilih%20Item%20Makanan%20%26%20Kuantiti%22%5D%0A%20%20%20%20B%20--%3E%7CTransaksi%20Langsung%7C%20D%5B%22Ketik%20Nominal%20Total%20Belanja%22%5D%0A%20%20%20%20C%20--%3E%20E%5B%223.%20Cek%20Saldo%20%26%20Batas%20Belanja%20Harian%22%5D%0A%20%20%20%20D%20--%3E%20E%0A%20%20%20%20E%20--%3E%20F%7B%22Metode%20Pembayaran%22%7D%0A%20%20%20%20F%20--%3E%7CDompet%20Digital%7C%20G%5B%22Saldo%20Terpotong%20Otomatis%20Realtime%22%5D%0A%20%20%20%20F%20--%3E%7CUang%20Tunai%7C%20H%5B%22Input%20Uang%20Diterima%20%26%20Hitung%20Kembalian%22%5D%0A%20%20%20%20G%20--%3E%20I%5B%224.%20Transaksi%20Sukses%20%26%20Cetak%20Struk%20Kasir%22%5D%0A%20%20%20%20H%20--%3E%20I%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<hr><h2 id="langkah-demi-langkah-mengoperasikan-kasir-pos" tabindex="-1">Langkah demi Langkah Mengoperasikan Kasir POS <a class="header-anchor" href="#langkah-demi-langkah-mengoperasikan-kasir-pos" aria-label="Permalink to &quot;Langkah demi Langkah Mengoperasikan Kasir POS&quot;">​</a></h2><h3 id="_1-mengidentifikasi-siswa-pembeli" tabindex="-1">1. Mengidentifikasi Siswa / Pembeli <a class="header-anchor" href="#_1-mengidentifikasi-siswa-pembeli" aria-label="Permalink to &quot;1. Mengidentifikasi Siswa / Pembeli&quot;">​</a></h3><p>Sebelum memproses belanjaan, sistem memerlukan identitas pembeli untuk memverifikasi kepemilikan saldo dan kuota belanja harian:</p><ul><li><strong>Metode Utama (Scan RFID)</strong>: <ol><li>Arahkan siswa untuk menempelkan kartu pelajar ke alat scanner RFID, atau tekan shortcut <strong><code>Ctrl + R</code></strong> / klik tombol hijau <strong><code>SCAN SEKARANG</code></strong>.</li><li>Sistem seketika mendeteksi identitas siswa. Foto siswa, Nama Lengkap, Kelas, Sisa Saldo Dompet Digital (<em>Wallet Balance</em>), dan Sisa Batas Jajan Hari Ini akan tampil pada panel kanan layar.</li></ol></li><li><strong>Metode Alternatif (Pencarian Manual)</strong>: Ketik <strong>NISN</strong>, <strong>NIP</strong>, atau <strong>Nama Siswa</strong> pada kolom pencarian di bagian atas, lalu klik nama siswa yang muncul pada dropdown.</li></ul><hr><h3 id="_2-memilih-mode-transaksi" tabindex="-1">2. Memilih Mode Transaksi <a class="header-anchor" href="#_2-memilih-mode-transaksi" aria-label="Permalink to &quot;2. Memilih Mode Transaksi&quot;">​</a></h3><p>Sistem POS menyediakan dua mode transaksi fleksibel sesuai kondisi antrean:</p><h4 id="a-mode-transaksi-langsung-direct-transaction-—-paling-cepat" tabindex="-1">A. Mode Transaksi Langsung (<em>Direct Transaction</em>) — Paling Cepat <a class="header-anchor" href="#a-mode-transaksi-langsung-direct-transaction-—-paling-cepat" aria-label="Permalink to &quot;A. Mode Transaksi Langsung (*Direct Transaction*) — Paling Cepat&quot;">​</a></h4><p>Mode ini digunakan jika kasir ingin langsung mengetik nominal belanjaan siswa tanpa mencatat detail jenis makanan satu per satu:</p><ol><li>Pastikan tab <strong>Transaksi Langsung</strong> aktif.</li><li>Masukkan nominal belanja pada kolom jumlah (tersedia tombol nominal cepat seperti <em>Rp 5.000</em>, <em>Rp 10.000</em>, <em>Rp 15.000</em>, <em>Rp 20.000</em>).</li><li>Tambahkan catatan belanja jika diperlukan.</li></ol><h4 id="b-mode-berbasis-menu-menu-catalog" tabindex="-1">B. Mode Berbasis Menu (<em>Menu Catalog</em>) <a class="header-anchor" href="#b-mode-berbasis-menu-menu-catalog" aria-label="Permalink to &quot;B. Mode Berbasis Menu (*Menu Catalog*)&quot;">​</a></h4><p>Mode ini digunakan untuk mencatat secara rinci menu apa saja yang dibeli siswa dan memotong stok makanan di kantin:</p><ol><li>Klik tab <strong>Menu</strong>.</li><li>Klik item makanan atau minuman pada katalog visual (misal: <em>Nasi Goreng</em>, <em>Donat Madu</em>, <em>Air Mineral</em>).</li><li>Item otomatis masuk ke keranjang belanja di sebelah kanan. Kasir dapat menambah/mengurangi jumlah kuantiti (<em>Qty</em>) menggunakan tombol <code>+</code> atau <code>-</code>.</li></ol><hr><h3 id="_3-memilih-metode-pembayaran" tabindex="-1">3. Memilih Metode Pembayaran <a class="header-anchor" href="#_3-memilih-metode-pembayaran" aria-label="Permalink to &quot;3. Memilih Metode Pembayaran&quot;">​</a></h3><h4 id="pembayaran-dengan-dompet-digital-siswa-wallet" tabindex="-1">Pembayaran dengan Dompet Digital Siswa (<code>Wallet</code>): <a class="header-anchor" href="#pembayaran-dengan-dompet-digital-siswa-wallet" aria-label="Permalink to &quot;Pembayaran dengan Dompet Digital Siswa (`Wallet`):&quot;">​</a></h4><ol><li>Klik tombol ungu <strong><code>Wallet</code></strong>.</li><li>Sistem secara otomatis memvalidasi dua hal penting: <ul><li><strong>Kecukupan Saldo</strong>: Saldo kartu harus lebih besar atau sama dengan total belanjaan.</li><li><strong>Batas Jajan Harian (Daily Limit)</strong>: Total belanja tidak boleh melebihi sisa jajan harian yang diatur orang tua siswa untuk hari itu.</li></ul></li><li>Klik tombol <strong>Proses Pembayaran</strong>.</li><li>Saldo dompet siswa terpotong secara instan dan notifikasi keberhasilan hijau akan muncul.</li></ol><h4 id="pembayaran-dengan-uang-tunai-cash" tabindex="-1">Pembayaran dengan Uang Tunai (<code>Cash</code>): <a class="header-anchor" href="#pembayaran-dengan-uang-tunai-cash" aria-label="Permalink to &quot;Pembayaran dengan Uang Tunai (`Cash`):&quot;">​</a></h4><ol><li>Jika siswa membawa uang tunai, klik tombol <strong><code>Cash</code></strong>.</li><li>Masukkan jumlah uang tunai yang diserahkan oleh siswa ke kolom <em>Uang Diterima</em>.</li><li>Sistem secara otomatis menghitung dan menampilkan nominal <strong>Uang Kembalian</strong> yang harus kasir serahkan ke siswa.</li><li>Klik <strong>Selesaikan Pembayaran Tunai</strong>.</li></ol><hr><h3 id="_4-cetak-struk-bukti-belanja-receipt" tabindex="-1">4. Cetak Struk Bukti Belanja (Receipt) <a class="header-anchor" href="#_4-cetak-struk-bukti-belanja-receipt" aria-label="Permalink to &quot;4. Cetak Struk Bukti Belanja (Receipt)&quot;">​</a></h3><p>Setelah pembayaran berhasil:</p><ol><li>Jendela modal struk belanja kasir akan muncul menampilkan rincian: No. Transaksi, Jam Transaksi, Nama Kasir, Daftar Makanan, Total Bayar, dan Sisa Saldo Siswa.</li><li>Kasir dapat menekan tombol <strong>Cetak Struk</strong> untuk mencetak kuitansi mini thermal (ukuran A8 / 58mm / 80mm).</li><li>Layar kasir akan otomatis ter-reset bersih dan siap melayani antrean siswa berikutnya.</li></ol><hr><h2 id="penanganan-kendala-di-kasir-pos" tabindex="-1">Penanganan Kendala di Kasir POS <a class="header-anchor" href="#penanganan-kendala-di-kasir-pos" aria-label="Permalink to &quot;Penanganan Kendala di Kasir POS&quot;">​</a></h2><ol><li><strong>Saldo Dompet Tidak Mencukupi</strong>: Layar akan menampilkan pesan merah peringatan. Siswa dapat: <ul><li>Membatalkan sebagian item belanjaan agar nominal mencukupi.</li><li>Membayar menggunakan uang tunai (<em>Cash</em>).</li><li>Melakukan isi ulang (<em>Top-Up</em>) saldo terlebih dahulu di loket koperasi.</li></ul></li><li><strong>Melebihi Batas Belanja Harian (Daily Limit Exceeded)</strong>: Meskipun saldo siswa masih banyak, transaksi akan ditolak jika orang tua siswa menetapkan batas jajan maksimal (misal: Rp 20.000/hari) dan siswa sudah menghabiskan kuotanya. Kasir harus menginformasikan bahwa kuota jajan hari ini sudah mencapai batas.</li><li><strong>Kartu Pelajar Fisik Rusak / Tertinggal</strong>: Kasir dapat mencari data siswa secara manual melalui kolom pencarian menggunakan Nama Lengkap atau NISN siswa, sehingga siswa tetap dapat berbelanja.</li></ol>',27))])}const _=t(g,[["render",p]]);export{M as __pageData,_ as default};
